const cfg = $json;
const raw = String(cfg.query_input || '').trim();
const normalized = raw.replace(/\s+/g, ' ').trim();
const lower = normalized.toLowerCase();

const eventMatch = normalized.match(/\bRF[XPIQ]?\s*[-#:]?\s*\d{3,8}(?:[-]\d{2,6})?\b/i)
  || normalized.match(/\bRFx[-\s]?\d{4}[-\s]?\d{3}\b/i);

let eventIdHint = '';
if (eventMatch) {
  eventIdHint = eventMatch[0].toUpperCase().replace(/\s+/g, '-').replace(/[:#]/g,'');
}

const explicitSupplier = /\b(i am|i'm|we are|we're|as a|our company is a)\s+(supplier|vendor|bidder)\b/i.test(normalized);
const explicitInternal = /\b(i am|i'm|we are|we're|as an?|our team is)\s+(buyer|procurement|sourcing|internal|category manager|stakeholder)\b/i.test(normalized);

const deterministicSensitive = [
  /\b(other|competitor|another)\s+(bid|bidder|supplier).*(price|score|proposal|submission)\b/i,
  /\b(rank|ranking|score|scoring)\b.*\b(other|competitor|bidder|supplier)\b/i,
  /\bnegotiat(e|ion|ing)\b.*\b(price|commercial|contract)\b/i,
  /\blegal advice\b/i,
  /\bconfidential\b.*\b(bid|evaluation|score|proposal)\b/i
].some(r => r.test(normalized));

const tokens = [...new Set(lower
  .replace(/[^a-z0-9\s-]/g,' ')
  .split(/\s+/)
  .filter(t => t.length > 2 && !['the','and','for','with','from','this','that','what','when','where','how','can','are','our','your','you'].includes(t)))];

return [{
  json: {
    ...cfg,
    queryText: normalized,
    queryLower: lower,
    queryTokens: tokens,
    eventIdHint,
    explicitRequestorType: explicitSupplier ? 'supplier' : (explicitInternal ? 'internal' : 'unknown'),
    deterministicSensitive,
    inputValid: normalized.length >= 3,
    interaction_id: 'INT-' + $execution.id + '-' + Date.now()
  }
}];

const d = $json;
const prompt = `You classify RFx sourcing-event questions. Return ONLY valid JSON, no markdown.

Schema:
{
  "requestor_type": "supplier|internal|unknown",
  "intent": "deadline|submission|eligibility|evaluation|documents|pricing|timeline|communication|amendment|confidentiality|general",
  "sensitivity": "none|competitor_bid|confidential_evaluation|negotiation|legal",
  "event_id": "",
  "needs_identity_clarification": false,
  "reason": "short reason"
}

Rules:
- Do not invent an event ID.
- If the person clearly identifies as supplier/vendor/bidder, requestor_type=supplier.
- If clearly procurement/sourcing/buyer/internal stakeholder, requestor_type=internal.
- Otherwise use unknown.
- Questions requesting another bidder's price, score, ranking, proposal, confidential evaluation detail, negotiation strategy, or legal advice are sensitive.
- "What are the published evaluation criteria?" is not sensitive by itself.
- Classification only. Do not answer the sourcing question.

Question: ${JSON.stringify(d.queryText)}
Explicit deterministic requestor hint: ${d.explicitRequestorType}
Event ID hint: ${d.eventIdHint || 'none'}`;

return [{json:{...d, classificationPrompt:prompt}}];

const base = $('Normalize and Precheck Inquiry').first().json;
const raw = String($json.text || $json.response || $json.output || '').replace(/```json|```/gi,'').trim();
let p = {};
try { p = JSON.parse(raw); } catch(e) { p = {}; }

const allowedTypes = ['supplier','internal','unknown'];
const allowedIntents = ['deadline','submission','eligibility','evaluation','documents','pricing','timeline','communication','amendment','confidentiality','general'];
const allowedSensitivity = ['none','competitor_bid','confidential_evaluation','negotiation','legal'];

let requestorType = allowedTypes.includes(String(p.requestor_type)) ? String(p.requestor_type) : 'unknown';
if (base.explicitRequestorType !== 'unknown') requestorType = base.explicitRequestorType;

let intent = allowedIntents.includes(String(p.intent)) ? String(p.intent) : 'general';
let sensitivity = allowedSensitivity.includes(String(p.sensitivity)) ? String(p.sensitivity) : 'none';
if (base.deterministicSensitive && sensitivity === 'none') sensitivity = 'confidential_evaluation';

const aiEventId = String(p.event_id || '').trim().toUpperCase();
const eventIdHint = base.eventIdHint || aiEventId;

return [{
  json:{
    ...base,
    requestorType,
    intent,
    sensitivity,
    eventIdHint,
    classification_parse_ok: Object.keys(p).length > 0,
    needsIdentityClarification: requestorType === 'unknown',
    classifierReason: String(p.reason || '')
  }
}];

const base = $('Validate Inquiry Classification').first().json;
const events = $('Fetch RFx Events').all().map(i => i.json || {}).filter(r => Object.keys(r).length);
const faqs = $('Fetch FAQ Rules').all().map(i => i.json || {}).filter(r => Object.keys(r).length);
const history = $('Fetch FAQ Usage History').all().map(i => i.json || {}).filter(r => Object.keys(r).length);

const s = v => v === null || v === undefined ? '' : String(v).trim();
const lower = v => s(v).toLowerCase();
const activeEvents = events.filter(e => !e.Status || ['active','open','published'].includes(lower(e.Status)));

let candidates = activeEvents.length ? activeEvents : events;
let resolved = null;
let resolution = 'unresolved';

if (base.eventIdHint) {
  resolved = candidates.find(e => lower(e.Event_ID) === lower(base.eventIdHint)) || null;
  resolution = resolved ? 'exact_id' : 'event_id_not_found';
} else {
  const q = lower(base.queryText);
  const named = candidates.filter(e => {
    const name = lower(e.Event_Name);
    return name && (q.includes(name) || name.split(/\s+/).filter(t=>t.length>4).filter(t=>q.includes(t)).length >= 2);
  });
  if (named.length === 1) {
    resolved = named[0];
    resolution = 'name_match';
  } else if (candidates.length === 1) {
    resolved = candidates[0];
    resolution = 'single_active_event';
  } else if (named.length > 1 || candidates.length > 1) {
    resolution = 'ambiguous';
  }
}

const eventStage = resolved ? s(resolved.Stage || 'Unknown') : 'Unknown';
const eventStatus = resolved ? s(resolved.Status || '') : '';

const sensitive = base.sensitivity !== 'none';
let route = 'answer';
let routeReason = '';

if (!base.inputValid) {
  route = 'clarify';
  routeReason = 'The question is empty or too short.';
} else if (base.needsIdentityClarification) {
  route = 'clarify';
  routeReason = 'Requestor type is not clear enough to apply supplier/internal access rules.';
} else if (sensitive) {
  route = 'escalate';
  routeReason = `Sensitive sourcing topic detected: ${base.sensitivity}.`;
} else if (!resolved) {
  route = resolution === 'ambiguous' ? 'clarify' : 'clarify';
  routeReason = resolution === 'event_id_not_found'
    ? `The referenced event ${base.eventIdHint} was not found.`
    : 'The sourcing event could not be resolved uniquely.';
}

return [{
  json:{
    ...base,
    route,
    routeReason,
    eventResolution: resolution,
    resolvedEventId: resolved ? s(resolved.Event_ID) : '',
    resolvedEventName: resolved ? s(resolved.Event_Name) : '',
    eventStage,
    eventStatus,
    eventRecord: resolved || {},
    eventCount: events.length,
    activeEventCount: activeEvents.length,
    faqCount: faqs.length,
    historyCount: history.length
  }
}];

const d = $json;
const faqs = $('Fetch FAQ Rules').all().map(i => i.json || {}).filter(r => Object.keys(r).length);
const s = v => v === null || v === undefined ? '' : String(v).trim();
const lower = v => s(v).toLowerCase();
const truthy = v => ['true','1','yes','y','active'].includes(lower(v));
const qTokens = new Set(d.queryTokens || []);
const stage = lower(d.eventStage);
const intent = lower(d.intent);
const eventId = lower(d.resolvedEventId);
const audience = lower(d.requestorType);

const scored = [];
for (const f of faqs) {
  if (f.Active !== undefined && s(f.Active) !== '' && !truthy(f.Active)) continue;

  const rowAudience = lower(f.Audience || 'both');
  const audienceAllowed = ['both','all',''].includes(rowAudience) || rowAudience === audience;
  if (!audienceAllowed) continue;

  const rowEvent = lower(f.Event_ID || 'all');
  if (rowEvent && !['all','*'].includes(rowEvent) && rowEvent !== eventId) continue;

  const rowStage = lower(f.Event_Stage || 'all');
  if (rowStage && !['all','*'].includes(rowStage) && rowStage !== stage) continue;

  const answer = audience === 'internal'
    ? s(f.Answer_Internal || f.Answer)
    : s(f.Answer_Supplier || f.Answer);
  if (!answer) continue;

  const text = [f.Question, f.Keywords, f.Category].map(lower).join(' ');
  const rowTokens = new Set(text.replace(/[^a-z0-9\s-]/g,' ').split(/\s+/).filter(t => t.length > 2));
  let overlap = 0;
  for (const t of qTokens) if (rowTokens.has(t)) overlap++;

  const tokenScore = qTokens.size ? overlap / qTokens.size : 0;
  const categoryBonus = lower(f.Category) === intent ? 0.30 : 0;
  const stageBonus = rowStage === stage ? 0.15 : 0;
  const eventBonus = rowEvent === eventId ? 0.20 : 0;
  const priorityBonus = lower(f.Priority) === 'high' ? 0.08 : lower(f.Priority) === 'medium' ? 0.04 : 0;
  const score = Math.min(1, tokenScore + categoryBonus + stageBonus + eventBonus + priorityBonus);

  scored.push({
    faq_id: s(f.FAQ_ID || f.Faq_ID || f.ID || ''),
    category: s(f.Category),
    question: s(f.Question),
    answer,
    stage: s(f.Event_Stage || 'All'),
    event_id: s(f.Event_ID || 'All'),
    priority: s(f.Priority || ''),
    score: Number(score.toFixed(3))
  });
}

scored.sort((a,b) => b.score - a.score);
const top = scored.slice(0,5);
const best = top[0]?.score || 0;

// Event fields can directly support common factual questions even when FAQ coverage is modest.
const eventFacts = d.eventRecord || {};
const eventFactIntents = ['deadline','submission','eligibility','timeline','communication','evaluation'];
const hasDirectEventFacts = eventFactIntents.includes(intent) && Object.keys(eventFacts).length > 0;
const threshold = Number(d.faq_coverage_threshold || 0.32);
const coverageSufficient = best >= threshold || hasDirectEventFacts;

return [{
  json:{
    ...d,
    authorizedFaqMatches: top,
    authorizedFaqIds: top.map(x=>x.faq_id).filter(Boolean),
    faqBestScore: best,
    faqCoverageSufficient: coverageSufficient,
    hasDirectEventFacts,
    retrievalCount: top.length
  }
}];

const d = $json;
const history = $('Fetch FAQ Usage History').all().map(i => i.json || {}).filter(r => Object.keys(r).length);
const s = v => v === null || v === undefined ? '' : String(v).trim();
const normalize = v => s(v).toLowerCase().replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
const tokens = txt => new Set(normalize(txt).split(' ').filter(t => t.length > 2 && !['the','and','for','with','from','this','that','what','when','where','how','can','are'].includes(t)));
const a = tokens(d.queryText);
const lookbackMs = Number(d.repeat_lookback_days || 30) * 86400000;
const cutoff = Date.now() - lookbackMs;

let similar = 0;
for (const row of history) {
  const dt = new Date(row.Timestamp || row.timestamp || row.Created_At || 0).getTime();
  if (dt && dt < cutoff) continue;
  const q = row.Question_Asked || row.question || row.Query || '';
  const b = tokens(q);
  if (!a.size || !b.size) continue;
  let inter = 0;
  for (const t of a) if (b.has(t)) inter++;
  const union = new Set([...a,...b]).size;
  const sim = union ? inter / union : 0;
  if (sim >= 0.55) similar++;
}

const repeatCountIncludingCurrent = similar + 1;
return [{
  json:{
    ...d,
    similarQuestionCount: similar,
    repeatQuestionCount: repeatCountIncludingCurrent,
    repeatedQuestion: repeatCountIncludingCurrent >= Number(d.repeat_question_threshold || 3)
  }
}];

const base = $('Analyze Repeat Question Demand').first().json;
const raw = String($json.text || $json.response || $json.output || '').replace(/```json|```/gi,'').trim();
let p = {};
try { p = JSON.parse(raw); } catch(e) { p = {}; }

const answer = String(p.answer || '').trim();
const confidence = Number(p.confidence);
const used = Array.isArray(p.used_faq_ids) ? p.used_faq_ids.map(String) : [];
const allowed = new Set((base.authorizedFaqIds || []).map(String));
const invalidCitations = used.filter(id => !allowed.has(id));

const forbiddenPatterns = [
  /\bcompetitor\b.*\b(price|bid|score|ranking)\b/i,
  /\bother bidder\b.*\b(price|score|ranking|proposal)\b/i
];
const forbiddenContent = base.requestorType === 'supplier' && forbiddenPatterns.some(r => r.test(answer));

const parseOk = Object.keys(p).length > 0;
const confidenceOk = Number.isFinite(confidence) && confidence >= Number(base.answer_confidence_threshold || 0.72);
const citationsOk = invalidCitations.length === 0;
const answerPresent = answer.length >= 20;
const modelNeedsHuman = p.needs_human === true;

const answerValid = parseOk && confidenceOk && citationsOk && answerPresent && !forbiddenContent && !modelNeedsHuman;
const reasons = [];
if (!parseOk) reasons.push('Gemini response was not valid JSON');
if (!answerPresent) reasons.push('No usable grounded answer was returned');
if (!confidenceOk) reasons.push(`Answer confidence ${Number.isFinite(confidence)?confidence:'invalid'} is below threshold`);
if (!citationsOk) reasons.push('Gemini referenced FAQ IDs outside the authorized retrieval set');
if (forbiddenContent) reasons.push('Potential restricted supplier-facing content detected');
if (modelNeedsHuman) reasons.push('Gemini explicitly requested human review');

return [{
  json:{
    ...base,
    generatedAnswer: answer,
    usedFaqIds: used,
    answerConfidence: Number.isFinite(confidence) ? confidence : 0,
    answerValid,
    answerValidationReason: reasons.join('; '),
    followUp: String(p.follow_up || ''),
    groundingNote: String(p.grounding_note || ''),
    escalationReason: reasons.join('; ') || 'Grounded answer validation failed'
  }
}];

const d = $json;
const gapId = 'GAP-' + $execution.id + '-' + Date.now();
const isRepeat = d.repeatedQuestion === true;
const response = `I don't have enough approved RFx information to answer this confidently for ${d.resolvedEventName || d.resolvedEventId}. I've routed the question for sourcing-team review rather than guessing.`;
return [{json:{
  ...d,
  gap_id:gapId,
  gap_status:'Pending Review',
  gap_priority:isRepeat ? 'High' : 'Normal',
  is_repeat_gap:isRepeat,
  escalationReason:`Knowledge coverage below threshold. Best FAQ score: ${d.faqBestScore}.`,
  proposed_response:response,
  final_response:response
}}];

const d=$json;
let response='';
if (d.needsIdentityClarification) {
  response='Before I answer, please tell me whether you are a supplier/vendor or an internal procurement/sourcing team member. This is required because RFx guidance can differ by audience.';
} else if (d.eventResolution === 'event_id_not_found') {
  response=`I could not find ${d.eventIdHint} in the active RFx event data. Please check the event ID and send it again.`;
} else {
  response='I found more than one possible RFx event. Please include the RFx event ID (for example, RFx-2026-001) so I can use the correct deadlines, stage, and rules.';
}
return [{json:{
  ...d,
  final_response:response,
  clarificationReason:d.routeReason || 'More context is required before applying RFx rules.'
}}];

let d=$json;
if (!d.queryText) {
  try {
    const gap = $('Prepare Knowledge Gap').item.json;
    if (gap && gap.queryText) d = gap;
  } catch(e) {}
}
const reason = d.escalationReason || d.routeReason || d.answerValidationReason || 'Human sourcing review required.';
const response = d.final_response || d.proposed_response || 'This question requires sourcing-team review because it is sensitive or cannot be answered safely from the approved RFx information. I have routed it for review.';
return [{json:{
  ...d,
  escalation_id:'ESC-' + $execution.id + '-' + Date.now(),
  escalationReason:reason,
  escalationStatus:'Pending',
  manager_email:d.sourcing_manager_email || '',
  final_response:response
}}];

const d=$('Prepare Sourcing Escalation').item.json;
const subject=`RFx FAQ escalation: ${d.resolvedEventId || d.eventIdHint || 'event clarification'} - ${d.intent || 'general'}`;
const html=`<div style="font-family:Arial,sans-serif;line-height:1.5">
<h2>RFx FAQ Assistant Escalation</h2>
<p><strong>Event:</strong> ${d.resolvedEventName || ''} (${d.resolvedEventId || d.eventIdHint || 'Unresolved'})</p>
<p><strong>Stage:</strong> ${d.eventStage || 'Unknown'}</p>
<p><strong>Requestor:</strong> ${d.requestorType || 'unknown'}</p>
<p><strong>Intent:</strong> ${d.intent || 'general'}</p>
<p><strong>Question:</strong> ${d.queryText}</p>
<p><strong>Reason:</strong> ${d.escalationReason}</p>
<p><strong>Interaction ID:</strong> ${d.interaction_id}</p>
</div>`;
return [{json:{...d,email_subject:subject,email_body:html}}];
